import base64, hashlib, json, os, pathlib, signal, subprocess, sys, time, traceback, urllib.request
from PIL import Image, ImageDraw

ROOT=pathlib.Path('/opt/probe/ComfyUI')
ART=pathlib.Path('/tmp/comfyctl-model-gate');ART.mkdir()
IMAGE_DIGEST=os.environ['GATE_IMAGE_DIGEST']
EXPECTED_CC=os.environ['GATE_EXPECTED_CC']
bridge=ART/'verify_worker_gpu.py';bridge.write_bytes(base64.b64decode(BRIDGE_SOURCE))
result={'kind':'sam3-da3-model-gpu-gate','image_digest':IMAGE_DIGEST,'expected_cc':EXPECTED_CC,'checks':{}}
server=None

def request(path,value=None):
 data=json.dumps(value).encode() if value is not None else None
 req=urllib.request.Request('http://127.0.0.1:8188'+path,data=data,headers={'Content-Type':'application/json'})
 with urllib.request.urlopen(req,timeout=20) as r:return json.load(r)

def run_graph(name,graph,expected_batch=1):
 started=time.monotonic();submitted=request('/prompt',{'prompt':graph})
 if submitted.get('node_errors'):raise RuntimeError('Graph validation: '+json.dumps(submitted))
 pid=submitted['prompt_id'];deadline=time.monotonic()+300
 while time.monotonic()<deadline:
  history=request('/history/'+pid)
  if pid in history:
   entry=history[pid]
   if entry['status']['status_str']!='success':raise RuntimeError(name+': '+json.dumps(entry['status']))
   texts=entry['outputs']['99']['text']
   stats=json.loads(texts[0])
   if stats['shape'][0]!=expected_batch or stats['shape'][-1]!=3:raise RuntimeError('Unexpected output shape: '+str(stats))
   item={'seconds':time.monotonic()-started,'stats':stats,'history_status':entry['status']}
   result['checks'][name]=item;print('MODEL_GATE_STEP='+json.dumps({name:item}),flush=True)
   return
  time.sleep(1)
 raise TimeoutError(name+' did not complete')

def download(repo,revision,filename,target,expected_hash,expected_size):
 from huggingface_hub import hf_hub_download
 directory=ROOT/'models'/pathlib.Path(target).parent;directory.mkdir(parents=True,exist_ok=True)
 downloaded=pathlib.Path(hf_hub_download(repo_id=repo,revision=revision,filename=filename,local_dir=str(directory)))
 h=hashlib.sha256()
 with downloaded.open('rb') as f:
  for data in iter(lambda:f.read(4*1024*1024),b''):h.update(data)
 if h.hexdigest()!=expected_hash or downloaded.stat().st_size!=expected_size:raise RuntimeError('Downloaded model hash/size mismatch')
 final=ROOT/'models'/target
 if downloaded!=final:downloaded.rename(final)
 result.setdefault('models',[]).append({'repo':repo,'revision':revision,'file':filename,'target':target,'sha256':h.hexdigest(),'size':expected_size})
 print('MODEL_VERIFIED='+json.dumps(result['models'][-1]),flush=True)


def deadline(signum,frame):raise TimeoutError('GPU suite reached its 15-minute execution limit')
signal.signal(signal.SIGALRM,deadline);signal.alarm(900)
try:
 print('GPU_SUITE_START',flush=True)
 subprocess.run(['python',str(bridge),'--expected-cc',EXPECTED_CC,'--expected-cuda','12.8','--image-digest',IMAGE_DIGEST,'--output',str(ART/'bridge.json')],check=True)
 result['bridge']=json.loads((ART/'bridge.json').read_text())
 download('depth-anything/DA3-SMALL','e08cab65ca0ec38e7826075418411ab90cab4da3','model.safetensors','depthanything3/da3_small.safetensors','364492e38a3a06d221ac75da7f6621ada3f2361cd24fde11ba79091e9f40efcf',137248940)
 download('apozz/sam3-safetensors','e88da2ed02aded4006f4711ee6a9c75d5aa38d0c','sam3.safetensors','sam3/sam3.safetensors','127037a7a11169c63a210b8e3e9caad24a66abdd65d3a78bbc3a7d8577d57026',3449860632)
 observer=ROOT/'custom_nodes/comfyctl_gate_observer';observer.mkdir()
 (observer/'__init__.py').write_text('''import json,torch
class Stats:
    @classmethod
    def INPUT_TYPES(cls):return {"required":{"image":("IMAGE",),"label":("STRING",),"nonzero":("BOOLEAN",)}}
    RETURN_TYPES=()
    FUNCTION="run"
    OUTPUT_NODE=True
    CATEGORY="test-only"
    def run(self,image,label,nonzero):
        if not torch.isfinite(image).all():raise RuntimeError("Non-finite model output")
        if nonzero and image.max().item()<=0:raise RuntimeError("Model produced an empty output")
        data={"label":label,"shape":list(image.shape),"dtype":str(image.dtype),"device":str(image.device),"min":image.min().item(),"max":image.max().item(),"mean":image.float().mean().item()}
        return {"ui":{"text":[json.dumps(data)]}}
NODE_CLASS_MAPPINGS={"ComfyctlGateTensorStats":Stats}
''')
 for idx,x in enumerate([112,128,144]):
  im=Image.new('RGB',(256,256),'white');d=ImageDraw.Draw(im)
  d.ellipse((x-52,76,x+52,180),fill='red');d.rectangle((18,195,90,244),fill='blue')
  (ROOT/'input').mkdir(exist_ok=True);im.save(ROOT/'input'/f'comfyctl-shape-{idx}.png')
 server=subprocess.Popen(['python','main.py','--use-pytorch-cross-attention','--listen','0.0.0.0','--port','8188'],cwd=ROOT)
 end=time.monotonic()+180
 while True:
  try:
   stats=request('/system_stats');break
  except Exception:
   if server.poll() is not None or time.monotonic()>end:raise RuntimeError('ComfyUI GPU startup failed')
   time.sleep(1)
 if not any(d['type']=='cuda' for d in stats['devices']):raise RuntimeError('ComfyUI did not use CUDA')
 result['system_stats']=stats
 load={'class_type':'LoadImage','inputs':{'image':'comfyctl-shape-0.png'}}
 def observe(source,label,nonzero=False):return {'class_type':'ComfyctlGateTensorStats','inputs':{'image':source,'label':label,'nonzero':nonzero}}
 depth={'1':load,'2':{'class_type':'DownloadAndLoadDepthAnythingV3Model','inputs':{'model':'da3_small.safetensors','precision':'bf16','attention':'sdpa'}},'3':{'class_type':'DepthAnything_V3','inputs':{'da3_model':['2',0],'images':['1',0],'normalization_mode':'V2-Style'}},'99':observe(['3',0],'da3-depth',True)}
 run_graph('da3_single',depth)
 sam={'1':load,'2':{'class_type':'LoadSAM3Model','inputs':{'precision':'bf16','compile':False}},'3':{'class_type':'SAM3CreatePoint','inputs':{'x':0.4375,'y':0.5,'is_foreground':True}},'4':{'class_type':'SAM3CombinePoints','inputs':{'point_1':['3',0]}},'5':{'class_type':'SAM3Segmentation','inputs':{'sam3_model_config':['2',0],'image':['1',0],'positive_points':['4',0],'refinement_iterations':0,'use_multimask':False,'output_best_mask':True}},'6':{'class_type':'MaskToImage','inputs':{'mask':['5',0]}},'99':observe(['6',0],'sam3-mask',True)}
 run_graph('sam3_image',sam)
 frames={'10':load,'11':{'class_type':'LoadImage','inputs':{'image':'comfyctl-shape-1.png'}},'12':{'class_type':'LoadImage','inputs':{'image':'comfyctl-shape-2.png'}},'13':{'class_type':'ImageBatch','inputs':{'image1':['10',0],'image2':['11',0]}},'14':{'class_type':'ImageBatch','inputs':{'image1':['13',0],'image2':['12',0]}}}
 depth_batch={**frames,'2':depth['2'],'3':{'class_type':'DepthAnything_V3','inputs':{'da3_model':['2',0],'images':['14',0],'normalization_mode':'V2-Style'}},'99':observe(['3',0],'da3-batch',True)}
 run_graph('da3_batch',depth_batch,3)
 video={**frames,'2':sam['2'],'3':sam['3'],'4':sam['4'],'20':{'class_type':'SAM3VideoSegmentation','inputs':{'prompt_mode':'point','video_frames':['14',0],'positive_points':['4',0],'frame_idx':0}},'21':{'class_type':'SAM3Propagate','inputs':{'sam3_model_config':['2',0],'video_state':['20',0],'start_frame':0,'end_frame':2,'direction':'forward'}},'22':{'class_type':'SAM3VideoOutput','inputs':{'masks':['21',0],'video_state':['21',2],'scores':['21',1]}},'23':{'class_type':'MaskToImage','inputs':{'mask':['22',0]}},'99':observe(['23',0],'sam3-video',True)}
 run_graph('sam3_video',video,3)
 result['status']='passed'
except BaseException:
 result['status']='failed';result['traceback']=traceback.format_exc()
finally:
 signal.alarm(0)
 if server is not None:
  server.terminate()
  try:server.wait(timeout=10)
  except subprocess.TimeoutExpired:server.kill();server.wait()
 result['scope']='Native worker GPU bridge plus actual SAM3 image/video and DA3 single/batch inference on synthetic images; no accuracy benchmark or full six-node certification'
 print('WORKER_GPU_SUITE_RESULT='+json.dumps(result),flush=True)
 time.sleep(600)
